-- Replace public.products from Sheetal_Product_Catalogue (2).xlsx
-- 1) Upload images/ into Storage bucket product-images under folder products/
-- 2) Run this in SQL → SQL Editor (not Logs)
begin;
delete from public.cart_items;
delete from public.wishlist;
delete from public.products;


do $$ begin perform setval(pg_get_serial_sequence('public.products','id'), (select coalesce(max(id),0) from public.products)); exception when others then null; end $$;
commit;
select count(*) as products, count(image_url) as with_image, count(*) filter (where price > 0) as with_price from public.products;